arguments.command:
cd /app; for f in seeds/*.csv; do python3 -c "
import sys
b=open('$f','rb').read()
try: b.decode('utf-8'); print('$f utf8', b[:3]==b'\xef\xbb\xbf', b'\r' in b)
except Exception as e: print('$f not utf8',e); b.decode('cp1252'); print(b'\r' in b)
"; done; cut -d, -f8 seeds/specimens.csv | sort | uniq -c; grep -c . seeds/*.csv
